    #[test]
    fn test_primitives() {
        let v = vec![1, 2, 3, 4, 5];
        let v2 = copy(&v);
        assert_eq!(v.len(), v2.len());
        assert_eq!(v, v2);
    }

    #[test]
    fn test_custom_copy_type() {
        #[derive(Copy, Clone, Debug, PartialEq)]
        struct Point { x: i32, y: i32 }

        let pts = vec![
            Point { x: 0, y: 0 },
            Point { x: 1, y: 2 },
            Point { x: 3, y: 4 },
        ];
        let pts2 = copy(&pts);

        assert_eq!(pts.len(), pts2.len());
        for i in 0..pts.len() {
            assert_eq!(pts[i], pts2[i]);
        }
    }
